arguments.script:
// Attack 1: a head commits src/vendor.mjs as a link to a file outside the checkout. node --check follows it and quotes
// the failing line, so a token on that line must not reach the stored and rendered finding.
import { mkdirSync, mkdtempSync, symlinkSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { pathToFileURL } from "node:url";

const token = "probe-secret-7d1e";
const scratch = mkdtempSync(join(tmpdir(), "outside-"));
const outside = join(scratch, "outside");
const checkout = join(scratch, "checkout");
mkdirSync(outside);
mkdirSync(join(checkout, "src"), { recursive: true });
writeFileSync(join(outside, "types.mjs"), `export const token = "${token}" +;\n`);
symlinkSync(join(outside, "types.mjs"), join(checkout, "src", "vendor.mjs"));
writeFileSync(join(checkout, "src", "index.mjs"), "export const ok = 1;\n");
const check = await import(pathToFileURL(join(process.cwd(), "src/syntax-check.mjs")).href);
const findings = check.checkFindings(checkout);
const rendered = check.render(findings);
console.log(`stored: ${JSON.stringify(findings)}\nrendered:\n${rendered}`);
if (findings.length !== 1 || findings[0].file !== join("src", "vendor.mjs")) process.exit(2);
process.exit(JSON.stringify(findings).includes(token) || rendered.includes(token) ? 1 : 0);
